insert into public.country_occupation_profiles (profile_key,country_code,canonical_career_id,official_title,official_code_system,official_code_version,official_unit_group_code,currency,registration_required,registration_authority,registration_url,publication_status,source_checked_at,updated_at) values ('AU:environmental-scientist','AU','environmental-scientist','Environmental Research Scientist (Environmental Scientist)','OSCA','2024 v1.0','2444','AUD',false,'VETASSESS assesses ANZSCO 234313 for migration skills assessment; no universal occupational registration','https://www.vetassess.com.au/check-my-occupation/professional-occupations/environmental-research-scientist','profile_ready','2026-08-09',now()) on conflict (profile_key) do update set official_title=excluded.official_title,official_code_system=excluded.official_code_system,official_code_version=excluded.official_code_version,official_unit_group_code=excluded.official_unit_group_code,currency=excluded.currency,registration_required=excluded.registration_required,registration_authority=excluded.registration_authority,registration_url=excluded.registration_url,publication_status=excluded.publication_status,source_checked_at=excluded.source_checked_at,updated_at=now();
insert into public.country_occupation_metric_snapshots (profile_key,as_of_date,employment_total,median_weekly_earnings,median_hourly_earnings,annualised_median_salary,all_occupations_median_weekly,part_time_share_pct,female_share_pct,median_age,average_full_time_hours,vacancies_three_month_avg,vacancy_period,vacancy_yoy_pct,employment_growth_5y_pct,employment_growth_10y_pct,shortage_component,vacancy_intensity_component,employer_diversity_component,vacancy_trend_component,entry_level_component,salary_component,growth_component,visa_component,entry_burden_component,opportunity_score,score_methodology_version,score_status,score_evidence,source_checked_at) values ('AU:environmental-scientist','2026-05-01',5500,null,null,null,1852,24,47,39,42,443.33333,'2026-05-01',-5.20,8.90,16.64,20,0,5,0,13,0,5,0,3,46,'career-opportunity-v1','provisional',jsonb_build_object('classification_scope','Environmental Scientist is the alternative title of current OSCA 244432 Environmental Research Scientist, Skill Level 1; Ecologist is separately classified.','anzsco_2022_mapping','Current ANZSCO 2022 occupation 234313 Environmental Research Scientist is the direct counterpart.','exact_profile',jsonb_build_object('employment_total',5500,'part_time_share_pct',24,'female_share_pct',47,'median_age',39,'average_full_time_hours',42,'scope','JSA six-digit legacy ANZSCO 234313 profile aligned to the current occupation'),'earnings_scope','JSA does not publish six-digit earnings for 234313. Broader 2343 earnings are context only, so salary credit is zero.','vacancy_scope','May 2026 IVI three-month-average vacancies are 443.33333 for broader ANZSCO 2343 versus 467.66667 in May 2025, about -5.20% year on year. Broader vacancies are not used for intensity.','projection_scope','Broader ANZSCO 2343 projections are +8.90% to 2030 and +16.64% to 2035; partial growth credit only.','shortage_note','JSA 2025 OSL records OSCA 244432 in shortage nationally and in all states and territories.','visa_basis','VETASSESS assesses ANZSCO 234313 as Group A, but the current CSOL instrument does not list 234313; no visa-list credit is awarded.','entry_level_basis','RMIT Bachelor of Environmental Science 110981J is a current three-year direct route; University of Melbourne Master of Environmental Science 092793M is a current two-year graduate route.','score_note','Exact employment/demographics and current shortage are retained; six-digit earnings are unavailable and broader vacancy/projection data are clearly scoped.'),'2026-08-09') on conflict (profile_key,as_of_date) do update set employment_total=excluded.employment_total,median_weekly_earnings=excluded.median_weekly_earnings,median_hourly_earnings=excluded.median_hourly_earnings,annualised_median_salary=excluded.annualised_median_salary,all_occupations_median_weekly=excluded.all_occupations_median_weekly,part_time_share_pct=excluded.part_time_share_pct,female_share_pct=excluded.female_share_pct,median_age=excluded.median_age,average_full_time_hours=excluded.average_full_time_hours,vacancies_three_month_avg=excluded.vacancies_three_month_avg,vacancy_period=excluded.vacancy_period,vacancy_yoy_pct=excluded.vacancy_yoy_pct,employment_growth_5y_pct=excluded.employment_growth_5y_pct,employment_growth_10y_pct=excluded.employment_growth_10y_pct,shortage_component=excluded.shortage_component,vacancy_intensity_component=excluded.vacancy_intensity_component,employer_diversity_component=excluded.employer_diversity_component,vacancy_trend_component=excluded.vacancy_trend_component,entry_level_component=excluded.entry_level_component,salary_component=excluded.salary_component,growth_component=excluded.growth_component,visa_component=excluded.visa_component,entry_burden_component=excluded.entry_burden_component,opportunity_score=excluded.opportunity_score,score_methodology_version=excluded.score_methodology_version,score_status=excluded.score_status,score_evidence=excluded.score_evidence,source_checked_at=excluded.source_checked_at;
